from typing import List

def parse_music(music_string: str) -> List[int]:
    beats = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    result = []
    notes = music_string.split()

    for note in notes:
        if note in beats:
            result.append(beats[note])
        elif note == 'o':
            result.append(beats['o'])

    return result

